package com.example.starter.observation;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 批量离线观测提交的单条条目：携带采集坐标、采集时刻与三个可编辑字段的完整候选值。
 *
 * @param submissionId   提交记录唯一标识
 * @param siteId         站点标识
 * @param observationId  目标观测记录标识
 * @param baseVersion    离线修改所基于的基线版本号
 * @param location       观测地点候选完整值
 * @param reading        观测读数候选完整值，十进制字符串，最多三位小数
 * @param note           观测备注候选完整值
 * @param latitude       采集纬度，范围 [-90,90]
 * @param longitude      采集经度，范围 [-180,180]
 * @param collectedAtUtc 采集时刻（UTC），服务端据此匹配围栏
 */
public record SubmissionItem(
        @NotBlank @Size(max = 128) String submissionId,
        @NotBlank @Size(max = 64) String siteId,
        @NotBlank @Size(max = 64) String observationId,
        @NotNull @Min(1) Integer baseVersion,
        @NotNull @Size(max = 512) String location,
        @NotNull @Pattern(regexp = "-?\\d+(\\.\\d{1,3})?", message = "reading must be a decimal string with at most 3 fraction digits")
        String reading,
        @NotNull @Size(max = 1024) String note,
        @NotNull BigDecimal latitude,
        @NotNull BigDecimal longitude,
        @NotNull Instant collectedAtUtc) {
}

package com.example.starter.observation;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 批量离线观测提交请求：可混合多个站点；任一条目格式错误整批回滚，不留下部分结果。
 *
 * @param requestId 全局唯一请求标识（幂等去重键）
 * @param operator  提交操作者标识
 * @param items     提交条目（按提交顺序处理，1~50 条）
 */
public record BatchSubmissionRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String operator,
        @NotNull @Size(min = 1, max = 50) List<@Valid SubmissionItem> items) {
}

package com.example.starter.observation;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 离线观测提交记录：对应 observation_submission 表的一行。
 * 原始坐标、采集时刻、提交时刻与匹配结果不可变；仅状态与合并版本可经人工裁决推进。
 *
 * @param submissionId        提交记录唯一标识
 * @param batchRequestId      所属批量提交的请求标识
 * @param batchSeq            批内顺序号，从 1 开始
 * @param siteId              站点标识
 * @param observationId       目标观测记录标识
 * @param baseVersion         离线修改所基于的基线版本号
 * @param location            观测地点候选完整值
 * @param reading             观测读数候选完整值（十进制原文）
 * @param note                观测备注候选完整值
 * @param latitude            采集纬度
 * @param longitude           采集经度
 * @param collectedAtUtc      采集时刻（UTC）
 * @param submittedAtUtc      服务端接收提交时刻（UTC）
 * @param status              状态：ACCEPTED / GEOFENCE_REJECTED / MANUAL_ACCEPTED
 * @param matchResult         围栏匹配结果：INSIDE / OUTSIDE / NO_FENCE
 * @param matchedFenceId      匹配到的围栏标识；NO_FENCE 时为 null
 * @param matchedFenceVersion 匹配到的围栏版本；NO_FENCE 时为 null
 * @param mergedVersion       自动或人工合并后的观测记录版本号；未合并（被拒）时为 null
 */
public record SubmissionRecord(
        String submissionId,
        String batchRequestId,
        int batchSeq,
        String siteId,
        String observationId,
        int baseVersion,
        String location,
        String reading,
        String note,
        BigDecimal latitude,
        BigDecimal longitude,
        Instant collectedAtUtc,
        Instant submittedAtUtc,
        String status,
        String matchResult,
        String matchedFenceId,
        Integer matchedFenceVersion,
        Integer mergedVersion) {

    /** 状态：围栏内自动合并接受。 */
    public static final String STATUS_ACCEPTED = "ACCEPTED";
    /** 状态：围栏外拒绝，保留原始证据，不参与自动合并。 */
    public static final String STATUS_GEOFENCE_REJECTED = "GEOFENCE_REJECTED";
    /** 状态：人工裁决接受。 */
    public static final String STATUS_MANUAL_ACCEPTED = "MANUAL_ACCEPTED";

    /** 匹配结果：落在围栏矩形内。 */
    public static final String MATCH_INSIDE = "INSIDE";
    /** 匹配结果：落在围栏矩形外。 */
    public static final String MATCH_OUTSIDE = "OUTSIDE";
    /** 匹配结果：采集时刻无生效围栏。 */
    public static final String MATCH_NO_FENCE = "NO_FENCE";
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 批量离线观测提交响应：整批处理结果，数量字段返回实际值。
 *
 * @param requestId     批量提交的请求标识
 * @param totalCount    本批条目总数（实际值）
 * @param acceptedCount 围栏内自动合并接受的条目数（实际值）
 * @param rejectedCount 围栏外拒绝的条目数（实际值）
 * @param items         逐条处理结果，按提交顺序排列
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record BatchSubmissionResponse(
        String requestId,
        int totalCount,
        int acceptedCount,
        int rejectedCount,
        List<ItemResult> items) {

    /**
     * 单条处理结果。
     *
     * @param submissionId        提交记录唯一标识
     * @param status              状态：ACCEPTED / GEOFENCE_REJECTED
     * @param matchResult         围栏匹配结果：INSIDE / OUTSIDE / NO_FENCE
     * @param matchedFenceId      匹配到的围栏标识（NO_FENCE 时不返回）
     * @param matchedFenceVersion 匹配到的围栏版本（NO_FENCE 时不返回）
     * @param mergedVersion       自动合并后的观测记录版本号（被拒时不返回）
     */
    @JsonInclude(JsonInclude.Include.NON_NULL)
    public record ItemResult(
            String submissionId,
            String status,
            String matchResult,
            String matchedFenceId,
            Integer matchedFenceVersion,
            Integer mergedVersion) {

        /**
         * 由提交记录构造单条结果。
         */
        public static ItemResult of(SubmissionRecord record) {
            return new ItemResult(record.submissionId(), record.status(), record.matchResult(),
                    record.matchedFenceId(), record.matchedFenceVersion(), record.mergedVersion());
        }
    }
}

