                // 右开：采集时刻等于生效终点，不命中
                item("sub-2", "site-A", "obs-2", 1, "站点A西", "3.0", "右边界", "31.5", "121", TO),
                // 生效前一刻，不命中
                item("sub-3", "site-A", "obs-3", 1, "站点A南", "4.0", "生效前", "31.5", "121",
