                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items[0].status").value("ACCEPTED"));

        // 变更围栏：新版本矩形不包含原采集点
        Map<String, Object> updateBody = new LinkedHashMap<>();
        updateBody.put("requestId", "req-f1");
