                .andExpect(jsonPath("$[0].adjudicationId").value("adj-1"))
                .andExpect(jsonPath("$[0].reason").value("现场核实坐标漂移，数据有效"));
    }

    @Test
    void adjudicateWithoutReasonReturns400() throws Exception {
        createSiteAFence("req-f0");
